def count_letter_digit_symbol_groups(s):
    if not s:
        return 0
    def kind(ch):
        if ch.isalpha():
            return 0
        if ch.isdigit():
            return 1
        return 2
    groups = 1
    prev = kind(s[0])
    for ch in s[1:]:
        k = kind(ch)
        if k != prev:
            groups += 1
            prev = k
    return groups

